import logging
import time

from selenium.common.exceptions import ElementClickInterceptedException, MoveTargetOutOfBoundsException
from selenium.webdriver.common.by import By

from taf.selenium.sbts_fsm3.common.common import LocalBasicPage
from taf.selenium.sbts_fsm3.common.exceptions import ParamValueError
from taf.selenium.sbts_fsm3.pages.modals import ValidationErrorsModal, OruRadioConfigurationWarningModal


def catch_target_exception(self, func, *args, **kwargs):
    interval = kwargs['interval']
    retry_times = kwargs['retry']

    timestamp_before_running = int(time.time())
    while retry_times:
        retry_times -= 1
        try:
            return func(self, *args, **kwargs)
        except ElementClickInterceptedException as e:
            if not retry_times:
                timestamp_after_running = int(time.time())
                logging.error(
                    'code raise error after running {}s'.format(timestamp_after_running - timestamp_before_running))
                raise ElementClickInterceptedException(e)
            time.sleep(interval)


def wait_for_operation_success(func):
    def wrapper(self, *args, **kwargs):
        return catch_target_exception(self, func, *args, **kwargs)

    return wrapper


class Menu(LocalBasicPage):
    """
    The class manages which menu tab will be clicked
    """
    LOGO_XPATH = '//div[@class="app-name ng-binding"]'
    CONFIGURATION_MANAGEMENT = "Configuration Management"
    DEFAULT_MENU_LENGTH = 3
    FIRST_MENU_INDEX = 0
    SECOND_MENU_INDEX = 1
    LAST_MENU_INDEX = -1
    _MAIN_MENU_XPATH = "//app-header//*[@ui-tooltip='{}']"
    _SUB_MENU_XPATH = "//app-header//*[text()='{}']"
    _TARGET_TAB_XPATH = '//li//*[text()="{}"]'
    _ACTIVE_TAB_XPATH = "//ng-view//li[contains(@class, 'highlight') or contains(@class, 'active')]/descendant::*"
    _ACTIVE_TITLE_XPATH = "//ng-view//h1[@class='ng-binding']"

    def __init__(self, driver):
        self._driver = driver
        super(Menu, self).__init__(driver)

    @wait_for_operation_success
    def open_page(self, menu_list, interval=3, retry=5):  # noqa: C901
        """
        Open a new page of selenium_sbts web, if target page has been opened, it won't be opened again
        :param menu_list: the menu list of selenium_sbts's page
        """
        if not menu_list:
            raise ParamValueError("menu list is empty")

        menu_xpath_list = []
        menu_xpath_list.append(self._MAIN_MENU_XPATH.format(menu_list[self.FIRST_MENU_INDEX]))
        menu_xpath_list.append(self._SUB_MENU_XPATH.format(menu_list[self.SECOND_MENU_INDEX]))
        if len(menu_list) == self.DEFAULT_MENU_LENGTH:
            menu_xpath_list.append(self._TARGET_TAB_XPATH.format(menu_list[self.LAST_MENU_INDEX]))

        if self._is_page_active(menu_list):
            return

        for index, xpath in enumerate(menu_xpath_list):
            if index != self.SECOND_MENU_INDEX:
                self.click_enabled_element_after_visible((By.XPATH, xpath))
            else:
                self.perform_element_hover_by_xpath(self.LOGO_XPATH)
                time.sleep(1)
                try:
                    self.perform_element_hover_by_xpath(xpath)
                except MoveTargetOutOfBoundsException:
                    self._scroll_elem_into_view(self.driver.find_element_by_xpath(xpath))
                    self.perform_element_hover_by_xpath(xpath)
                self.click_enabled_element((By.XPATH, xpath))
                self.check_pop_up_window(menu_list[self.SECOND_MENU_INDEX])

    def _is_page_active(self, menu_list):
        if self.element_exists((By.XPATH, self._ACTIVE_TAB_XPATH), timeout=1):
            return menu_list[self.LAST_MENU_INDEX] == self.get_text_by_xpath(self._ACTIVE_TAB_XPATH)
        else:
            return menu_list[self.LAST_MENU_INDEX] == self.get_text_by_xpath(self._ACTIVE_TITLE_XPATH)

    def check_pop_up_window(self, sub_menu):
        if sub_menu == self.CONFIGURATION_MANAGEMENT:
            validation_errors = ValidationErrorsModal(self._driver)
            validation_errors.wait_until_validation_errors_modal()
            validation_errors.close()

            radio_configuration_waring_modal = OruRadioConfigurationWarningModal(self._driver)
            radio_configuration_waring_modal.wait_until_radio_configuration_warning_modal_appear()
            radio_configuration_waring_modal.close()
